<script setup lang="ts">
import type { TagDto } from '~/types/api'
import { errorMessage } from '~/utils/format'
const { refresh } = useAppData()
const items = ref<TagDto[]>([]), search = ref(''), error = ref(''), open = ref(false), saving = ref(false), editingId = ref<string | null>(null), deleteOpen = ref(false), deleting = ref<TagDto | null>(null)
const form = reactive({ name: '', disabled: false })
const filtered = computed(() => items.value.filter(item => item.name.toLocaleLowerCase().includes(search.value.trim().toLocaleLowerCase())))
async function load() { try { items.value = await $fetch<TagDto[]>('/api/tags'); error.value = '' } catch (cause) { error.value = errorMessage(cause) } }
function edit(item?: TagDto) { editingId.value = item?.id ?? null; form.name = item?.name ?? ''; form.disabled = item?.disabled ?? false; error.value = ''; open.value = true }
async function save() { if (saving.value) return; if (!form.name.trim()) { error.value = '请填写标签名称'; return } saving.value = true; error.value = ''; try { await $fetch(editingId.value ? `/api/tags/${editingId.value}` : '/api/tags', { method: editingId.value ? 'PUT' : 'POST', body: form, retry: 0 }); await refresh(); await load(); open.value = false } catch (cause) { error.value = errorMessage(cause) } finally { saving.value = false } }
async function remove() { if (!deleting.value || saving.value) return; saving.value = true; error.value = ''; try { await $fetch(`/api/tags/${deleting.value.id}`, { method: 'DELETE', query: { confirm: true }, retry: 0 }); await refresh(); await load(); deleteOpen.value = false } catch (cause) { error.value = errorMessage(cause) } finally { saving.value = false } }
onMounted(load)
</script>
<template><section class="space-y-3"><div class="section-heading"><h2 class="section-title">标签管理</h2><UButton label="新增标签" color="neutral" variant="outline" @click="edit()" /></div><UInput v-model="search" type="search" placeholder="搜索标签" aria-label="搜索标签" icon="i-lucide-search" class="w-full" /><UAlert role="alert" v-if="error && !open && !deleteOpen" :description="error" color="error" />
<ul v-if="filtered.length" class="group-list"><li v-for="tag in filtered" :key="tag.id" class="list-row"><NuxtLink :to="`/tags/${tag.id}`" class="row-body"><p class="font-medium">{{ tag.name }}<span v-if="tag.disabled" class="ml-2 text-xs text-muted">已停用</span></p><p class="text-xs text-muted">{{ tag.usageCount }} 条关联记录</p></NuxtLink><UButton icon="i-lucide-pencil" :aria-label="`编辑标签${tag.name}`" color="neutral" variant="ghost" @click="edit(tag)" /><UButton icon="i-lucide-trash-2" :aria-label="`删除标签${tag.name}`" color="error" variant="ghost" :disabled="tag.usageCount > 0" @click="deleting = tag; error = ''; deleteOpen = true" /></li></ul><EmptyState v-else :title="search ? '没有匹配标签' : '暂无标签'" />
<UModal v-model:open="open" :title="editingId ? '编辑标签' : '新增标签'" :dismissible="!saving" :close="!saving"><template #body><div class="space-y-3"><UAlert role="alert" v-if="error" :description="error" color="error" /><UFormField label="标签名称" required><UInput v-model="form.name" :maxlength="40" :disabled="saving" class="w-full" data-testid="tag-name" /></UFormField><UCheckbox v-model="form.disabled" label="停用（保留历史记录，不再用于新增）" :disabled="saving" /></div></template><template #footer><UButton label="取消" color="neutral" variant="outline" :disabled="saving" @click="open = false" /><UButton label="保存" :loading="saving" data-testid="tag-save" @click="save" /></template></UModal>
<UModal v-model:open="deleteOpen" :title="`删除标签「${deleting?.name ?? ''}」？`" description="删除后无法恢复" :dismissible="!saving" :close="!saving"><template #body><UAlert role="alert" v-if="error" :description="error" color="error" /></template><template #footer><UButton label="取消" color="neutral" variant="outline" :disabled="saving" @click="deleteOpen = false" /><UButton label="删除" color="error" :loading="saving" @click="remove" /></template></UModal>
</section></template>
